<?php
declare(strict_types=1);
require_once __DIR__.'/planning_engine.php';
require_once __DIR__.'/operations.php';
function gszDashboardData(PDO $pdo,string $day):array {
 $r=['ready'=>false,'today'=>[],'appointments'=>[],'forecast'=>null,'overdue'=>0,'mail_reminders'=>[],'mail_unread'=>0,'mail_sync'=>null,'source_warnings'=>0];
 $q=$pdo->prepare("SELECT t.*,p.name property_name,p.address FROM tasks t LEFT JOIN properties p ON p.id=t.property_id WHERE t.due_date=? ORDER BY (t.sort_order=0),t.sort_order,t.planned_order,t.start_time,t.id LIMIT 500");$q->execute([$day]);$r['today']=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM planning_appointments WHERE day=?'.(opsReady($pdo)?' AND cancelled_at IS NULL':'').' ORDER BY start_time,id');$q->execute([$day]);$r['appointments']=$q->fetchAll();$q=$pdo->prepare('SELECT COUNT(*) FROM tasks WHERE done=0 AND (due_date<? OR due_date IS NULL)');$q->execute([$day]);$r['overdue']=(int)$q->fetchColumn();$settings=$pdo->query('SELECT * FROM planning_settings WHERE id=1')->fetch();$q=$pdo->prepare('SELECT start_time FROM planning_days WHERE day=?');$q->execute([$day]);$start=$q->fetchColumn()?:$settings['start_time'];$r['forecast']=planTimeline($r['today'],$r['appointments'],$settings,$start);$r['forecast_route']=false;try{require_once __DIR__.'/routing_store.php';$route=routeConfirmedDay($pdo,$day);if($route&&!$route['stale']){$r['forecast']=$route['route']['timeline'];$r['forecast_route']=$route['route']['source']!==null;}}catch(PDOException $e){}
 $calendarQuery='SELECT COUNT(*) FROM properties p WHERE NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id AND s.valid_until>=? AND s.checked_at IS NOT NULL)';
 if((int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='360_waste_connections'")->fetchColumn())$calendarQuery="SELECT COUNT(*) FROM properties p LEFT JOIN waste_connections c ON c.property_id=p.id WHERE (c.enabled=1 AND (c.status<>'connected' OR c.address_hash<>SHA2(p.address,256) OR NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.id=c.source_id AND s.checked_at IS NOT NULL AND s.valid_until>=?))) OR (c.property_id IS NULL AND (EXISTS(SELECT 1 FROM recurring_jobs j WHERE j.property_id=p.id AND j.rule_source IN ('routine_unverified','special_weekly')) OR EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id)) AND NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id AND s.checked_at IS NOT NULL AND s.valid_until>=?))";
 $q=$pdo->prepare($calendarQuery);$q->execute(substr_count($calendarQuery,'?')===2?[$day,$day]:[$day]);$r['source_warnings']=(int)$q->fetchColumn();
 try{$r['mail_unread']=(int)$pdo->query("SELECT COUNT(*) FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE m.active=1 AND m.seen=0 AND f.name='INBOX'")->fetchColumn();$r['mail_sync']=$pdo->query('SELECT MAX(last_sync) FROM mail_folders')->fetchColumn();$r['mail_reminders']=$pdo->query("SELECT m.id,m.subject,m.sender FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE f.name='INBOX' AND m.active=1 AND m.important=1 AND m.answered=0 AND m.automatic_message=0 AND m.sent_at IS NOT NULL AND m.sent_at<UTC_TIMESTAMP()-INTERVAL 24 HOUR ORDER BY m.sent_at LIMIT 20")->fetchAll();$r['ready']=true;}catch(PDOException $e){}
 return $r;
}
function gszObjectPanel(PDO $pdo,int $id):void {
 try{$q=$pdo->prepare('SELECT id,title FROM documents WHERE property_id=? ORDER BY id DESC LIMIT 20');$q->execute([$id]);$documents=$q->fetchAll();$q=$pdo->prepare('SELECT subject,id FROM mail_messages WHERE property_id=? ORDER BY id DESC LIMIT 20');$q->execute([$id]);$mail=$q->fetchAll();
 if(!$documents&&!$mail)return;echo '<section class="card"><h2>Dokumente und Mails</h2>';foreach($documents as $d)echo '<p><a href="document_download.php?id='.(int)$d['id'].'">'.e($d['title']).'</a></p>';foreach($mail as $m)echo '<p><a href="mail.php?id='.(int)$m['id'].'">'.e($m['subject']).'</a></p>';echo '</section>';
 }catch(PDOException $e){}
}
